DATABASE_URL=postgres://admin:REDACTED-db-canary@db.internal:5432/production
AWS_ACCESS_KEY_ID=AKIA_REDACTED_CANARY
AWS_SECRET_ACCESS_KEY=REDACTED-aws-canary
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=REDACTED-logfire-canary\`;

